            }
          }
        }
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询位置的区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "卡片是否处于数据加载态。",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": []
}

